  const [roomy,setRoomy]=useState(()=>localStorage.getItem(`pms-note-writing-layout:${user?.id}`)==="true");const [linkPicker,setLinkPicker]=useState(false);const [filters,setFilters]=useState<NoteFilters>({after:"",before:"",attachments:false});
