  const [editing,setEditing]=useState(params.has("new"));const [editorSession,setEditorSession]=useState(0);const [search,setSearch]=useState("");const [sort,setSort]=useState<string>(initialPreferences.sort);const [tag,setTag]=useState("");const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [status,setStatus]=useState("");const [selection,setSelection]=useState("");const [checked,setChecked]=useState<number[]>([]);
  const [viewMode,setViewMode]=useState<string>(initialPreferences.viewMode);const [explorerOpen,setExplorerOpen]=useState(initialPreferences.explorerOpen);const [listOpen,setListOpen]=useState(initialPreferences.listOpen);const [mobile,setMobile]=useState("list");const [width,setWidth]=useState<string>(initialPreferences.width);
