  const [modal,setModal]=useState<"folder"|"move"|"share"|"history"|"templates"|"reference"|"link"|"shortcuts"|null>(null);const [folderEdit,setFolderEdit]=useState<Partial<NoteFolder>>({});const [context,setContext]=useState<NoteScope>(scope);const [moveTarget,setMoveTarget]=useState("personal");const [shareEmail,setShareEmail]=useState("");const [shares,setShares]=useState<{user_id:number;email:string}[]>([]);const [revisions,setRevisions]=useState<Revision[]>([]);const [preview,setPreview]=useState<Revision|null>(null);const [referenceKind,setReferenceKind]=useState<"task"|"project">("project");const [referenceId,setReferenceId]=useState("");const [createTaskProject,setCreateTaskProject]=useState<number|null>(null);const [attachmentRefresh,setAttachmentRefresh]=useState(0);const [treeSession,setTreeSession]=useState(0);
  const [visibilityChoice,setVisibilityChoice]=useState("private");const [audienceConfirmed,setAudienceConfirmed]=useState(false);
