  useEffect(()=>{if(!params.size&&!projectId&&initialPreferences.noteId){setParams({note:String(initialPreferences.noteId)},{replace:true});}},[]);
  const listParams={modified_after:filters.after||undefined,modified_before:filters.before||undefined,has_attachments:filters.attachments,view:["favorites","recent","shared","archive","trash","quick"].includes(scope.kind)?scope.kind:"all",q:search,sort,tag,personal:scope.kind==="personal",project_id:scope.project_id||undefined,task_id:scope.task_id||undefined,folder_id:scope.folder_id||undefined};
