  useEffect(()=>{if(recovery||readOnly||!editing)return;try{if(dirty)sessionStorage.setItem(draftKey(note?.id),JSON.stringify({draft,date:new Date().toISOString()}));else sessionStorage.removeItem(draftKey(note?.id));}catch{}},[draft,saved,note?.id,recovery,readOnly,editing]);
  function apply(data:NoteRecord){editingRef.current=true;noteRef.current=data;setNote(data);setDraft(draftFrom(data));setSaved(draftFrom(data));setEditing(true);setEditorSession(v=>v+1);setSelection("");setError("");setStatus("Saved");setMobile("editor");try{const stored=JSON.parse(sessionStorage.getItem(draftKey(data.id))||"null");setRecovery(stored&&!same(stored.draft,draftFrom(data))?stored:null);}catch{setRecovery(null);}}
  function mayLeave(){return !lock.current&&(!dirtyRef.current||window.confirm("Leave this note? Your unsaved draft will be kept for recovery."));}
  async function open(id:number,updateUrl=true){if(!mayLeave()){if(!updateUrl&&noteRef.current){const next=new URLSearchParams(params);next.set("note",String(noteRef.current.id));setParams(next,{replace:true});}return;}lock.current=true;setBusy(true);try{const loaded=(await api.get<NoteRecord>(`${noteBase}/${id}`)).data;apply(loaded);if(firstOpen.current){firstOpen.current=false;if(!scopeContainsNote(scope,loaded))setScope(loaded.deleted_at?{kind:"trash",title:"Trash"}:loaded.archived?{kind:"archive",title:"Archived"}:loaded.can_edit===false?{kind:"shared",title:"Shared With Me"}:{kind:"all",title:"All Notes"});}if(updateUrl){const next=new URLSearchParams(params);next.set("note",String(id));next.delete("new");setParams(next);}}catch(e){setError(workspaceError(e));}finally{lock.current=false;setBusy(false);}}
  const requested=Number(params.get("note"));
  useEffect(()=>{if(requested&&requested!==noteRef.current?.id)void open(requested,false);},[requested]);
  useEffect(()=>{if(!requested&&!editingRef.current&&!loading&&notes[0])void open(notes[0].id);},[loading,notes.length]);
  function create(target:NoteScope=scope,template=templates[0]){if(!mayLeave())return;editingRef.current=true;const empty=blankNote(target);empty.title=template.content?template.name:"";empty.content=template.content?RICH_TEXT_PREFIX+template.content:"";setNote(null);setDraft(empty);setSaved(blankNote(target));setEditing(true);setEditorSession(v=>v+1);setSelection("");setError("");setStatus("New note");setRecovery(null);setMobile("editor");setModal(null);const next=new URLSearchParams(params);next.delete("note");next.delete("new");setParams(next);if(!template.content){try{const stored=JSON.parse(sessionStorage.getItem(draftKey())||"null");if(stored)setRecovery(stored);}catch{}}}
  useEffect(()=>{if(params.has("new")&&!lock.current&&!dirtyRef.current)create(scope);},[params.get("new")]);
  async function save():Promise<NoteRecord|null>{if(lock.current||readOnly)return null;if(!dirtyRef.current&&noteRef.current)return noteRef.current;const before=draftRef.current;const snapshot={...before,title:before.title.trim()||"Untitled note"};const current=noteRef.current;lock.current=true;setBusy(true);setStatus("Saving…");setError("");try{const {data}=current?await api.put<NoteRecord>(`${noteBase}/${current.id}`,{...snapshot,version:current.version}):await api.post<NoteRecord>(noteBase,snapshot);setNote(data);noteRef.current=data;setSaved(draftFrom(data));if(same(draftRef.current,before))setDraft(draftFrom(data));setStatus("Saved");if(!current){sessionStorage.removeItem(draftKey());const next=new URLSearchParams(params);next.set("note",String(data.id));setParams(next,{replace:true});}void refresh().catch(()=>{});return data;}catch(e){setStatus("Save failed — draft kept");setError(workspaceError(e));return null;}finally{lock.current=false;setBusy(false);}}
