  function chooseScope(next:NoteScope){setScope(next);setFilters({after:"",before:"",attachments:false});setChecked([]);selectionAnchor.current=null;setSearch("");setTag("");setMobile("list");}
  function scopeForFolder(id:number):NoteScope{const folder=folders.find(f=>f.id===id)!;return {kind:"folder",title:folder.name,folder_id:id,project_id:folder.project_id,task_id:folder.task_id};}
  async function bulk(action:string,ids=checked,target?:NoteScope){if(!ids.length||busy)return;let current=noteRef.current;if(current&&ids.includes(current.id)&&dirtyRef.current){current=await save();if(!current)return;}const snapshots=ids.map(id=>(current?.id===id?current:null)||notes.find(n=>n.id===id)||allNotes.find(n=>n.id===id)).filter(Boolean) as NoteRecord[];if(snapshots.length!==ids.length){setError("Reload the notes list before changing this selection.");return;}if(action==="trash"&&!window.confirm(`Move ${ids.length} note(s) to Trash? You can restore them later.`))return;setBusy(true);setError("");try{const changed=await api.post<{items:{id:number;version:number}[]}>("/project-management/note-actions/bulk",{action,items:snapshots.map(n=>({id:n.id,version:n.version})),...(action==="move"?{folder_id:target?.folder_id||null,project_id:target?.project_id||null,task_id:target?.task_id||null}:{})});const returned=new Map(changed.data.items.map(item=>[item.id,item.version]));const label=`${ids.length} note${ids.length===1?"":"s"} ${action==="move"?"moved":action==="trash"?"moved to Trash":action==="archive"?"archived":action==="unarchive"?"unarchived":"restored"}`;setUndoAction({label,items:snapshots.map(item=>({id:item.id,version:returned.get(item.id)!,project_id:item.project_id,task_id:item.task_id,folder_id:item.folder_id,archived:item.archived,trashed:!!item.deleted_at}))});setAnnouncement(label);setChecked([]);setModal(null);await refresh();if(note&&ids.includes(note.id))apply((await api.get<NoteRecord>(`${noteBase}/${note.id}`)).data);}catch(e){setError(workspaceError(e));}finally{setBusy(false);}}
  async function undoManagementAction(){if(!undoAction||busy)return;if(dirtyRef.current&&undoAction.items.some(item=>item.id===noteRef.current?.id)){setError("Save your draft before undoing this action. Undo cannot replace newer edits.");return;}setBusy(true);setError("");try{await api.post("/project-management/note-actions/undo",{items:undoAction.items});setUndoAction(null);setAnnouncement("Action undone");await refresh();const id=noteRef.current?.id;if(id&&undoAction.items.some(item=>item.id===id))apply((await api.get<NoteRecord>(`${noteBase}/${id}`)).data);}catch(e){setError(workspaceError(e));}finally{setBusy(false);}}
  function selectCard(event:MouseEvent,item:NoteRecord){if(!event.shiftKey&&!event.ctrlKey&&!event.metaKey){selectionAnchor.current=item.id;void open(item.id);return;}event.preventDefault();if(item.can_edit===false)return;const ordered=[...notes.filter(value=>value.pinned),...notes.filter(value=>!value.pinned)];if(event.shiftKey){const start=ordered.findIndex(value=>value.id===(selectionAnchor.current||note?.id||item.id));const end=ordered.findIndex(value=>value.id===item.id);const range=ordered.slice(Math.min(Math.max(0,start),end),Math.max(start,end)+1).filter(value=>value.can_edit!==false).map(value=>value.id);setChecked(current=>[...new Set([...current,...range])].slice(0,200));}else{selectionAnchor.current=item.id;setChecked(current=>current.includes(item.id)?current.filter(id=>id!==item.id):[...current,item.id].slice(0,200));}}
  function treeAction(action:string,target:NoteScope,folder?:NoteFolder){setContext(target);if(action==="new")create(target);else if(["folder","rename","style"].includes(action)){setFolderEdit((action!=="folder"?folder:undefined)||{name:"",parent_id:target.folder_id||null,project_id:target.project_id||null,task_id:target.task_id||null,color:"#8b5cf6",icon:"folder",position:folders.length*10});setModal("folder");}else if(action==="link"){setChecked([]);setModal("link");}else if(action==="task")setCreateTaskProject(target.project_id||null);else if(folder&&action==="deleteFolder"){if(window.confirm("Remove this empty folder? Notes and populated folders will not be deleted."))void api.delete(`/project-management/note-folders/${folder.id}`,{data:{version:folder.version}}).then(()=>refresh()).catch(e=>setError(workspaceError(e)));}else if(folder&&(action==="up"||action==="down")){const siblings=folders.filter(item=>item.parent_id===folder.parent_id&&item.project_id===folder.project_id&&item.task_id===folder.task_id);const adjacent=siblings[siblings.findIndex(item=>item.id===folder.id)+(action==="up"?-1:1)];if(adjacent)void api.post(`/project-management/note-folders/${folder.id}/move`,{version:folder.version,target_id:adjacent.id,placement:action==="up"?"before":"after"}).then(()=>refresh()).catch(e=>setError(workspaceError(e)));}}
  async function updateFolder(folder:NoteFolder,changes:Partial<NoteFolder>){const {id,count,...body}=folder;try{await api.put(`/project-management/note-folders/${id}`,{...body,...changes});await refresh();}catch(e){setError(workspaceError(e));}}
  async function saveFolder(){setBusy(true);try{const {id,count,...body}=folderEdit;const saved=id?await api.put(`/project-management/note-folders/${id}`,body):await api.post("/project-management/note-folders",body);await refresh();setModal(null);chooseScope({kind:"folder",title:saved.data.name,folder_id:saved.data.id,project_id:saved.data.project_id,task_id:saved.data.task_id});}catch(e){setError(workspaceError(e));}finally{setBusy(false);}}
  async function duplicate(){if(!note||busy||dirty)return;try{const data=(await api.post<NoteRecord>(`${noteBase}/${note.id}/duplicate`)).data;apply(data);const next=new URLSearchParams(params);next.set("note",String(data.id));setParams(next);await refresh();}catch(e){setError(workspaceError(e));}}
