  async function share(){if(!note||dirty){setError("Save your note before sharing.");return;}try{setShares((await api.get(`${noteBase}/${note.id}/shares`)).data);setShareEmail("");setModal("share");}catch(e){setError(workspaceError(e));}}
  async function uploadImage(file:File){const current=await save();if(!current)throw new Error("Save the note before inserting an image.");const form=new FormData();form.append("file",file);const {data}=await api.post(`${noteBase}/${current.id}/attachments`,form,{uploadLimitBytes:10*1024*1024});setAttachmentRefresh(v=>v+1);return data;}
  function attach(){if(attachmentsRef.current){attachmentsRef.current.closest("details")?.setAttribute("open","");attachmentsRef.current.scrollIntoView({behavior:"smooth"});attachmentsRef.current.querySelector<HTMLButtonElement>('button')?.click();}else void save().then(data=>{if(data)setTimeout(()=>{attachmentsRef.current?.closest("details")?.setAttribute("open","");attachmentsRef.current?.querySelector<HTMLButtonElement>('button')?.click();},100);});}
  function downloadText(value:string,extension:string){const url=URL.createObjectURL(new Blob([value],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=(draft.title||"note").replace(/[^a-z0-9_-]/gi,"_")+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function exportPdf(){const current=readOnly?note:await save();if(!current)return;try{const {data}=await api.get(`${noteBase}/${current.id}/export.pdf`,{responseType:"blob"});const url=URL.createObjectURL(data);const a=document.createElement("a");a.href=url;a.download=(current.title||"note")+".pdf";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){setError(workspaceError(e));}}
  function print(){const popup=window.open("","_blank");if(!popup){setError("Allow the print window to open, then try again.");return;}popup.opener=null;popup.document.title=draft.title||"Note";const style=popup.document.createElement("style");style.textContent="body{font:15px/1.8 Arial;margin:40px;max-width:1000px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:8px}blockquote{border-left:3px solid #7853d9;padding:12px}pre{white-space:pre-wrap;background:#f4f4f8;padding:16px}";popup.document.head.append(style);const title=popup.document.createElement("h1");title.textContent=draft.title||"Untitled note";popup.document.body.append(title);const body=popup.document.createElement("article");body.innerHTML=contentToHtml(draft.content);popup.document.body.append(body);popup.focus();popup.print();}
  function resize(event:PointerEvent,index:number){const start=event.clientX,prior=panelSizes[index];event.currentTarget.setPointerCapture(event.pointerId);const element=event.currentTarget;const move=(e:globalThis.PointerEvent)=>{setPanelSizes(current=>{const next=[...current];next[index]=Math.max(index===0?210:250,Math.min(index===0?340:440,prior+e.clientX-start));localStorage.setItem("pms-notes-panel-sizes",JSON.stringify(next));return next;});};const end=()=>{element.removeEventListener("pointermove",move as EventListener);element.removeEventListener("pointerup",end);};element.addEventListener("pointermove",move as EventListener);element.addEventListener("pointerup",end);}
