    <NotesExplorer key={treeSession} busy={busy} projects={projects} folders={folders} notes={allNotes} scope={scope} onScope={chooseScope} onOpen={id=>void open(id)} onAction={treeAction} onDrop={(ids,target)=>void bulk("move",ids,target)} onFolderDrop={(id,target,placement)=>{const folder=folders.find(f=>f.id===id);if(folder)void api.post(`/project-management/note-folders/${id}/move`,{version:folder.version,target_id:target.id,placement}).then(()=>refresh()).catch(e=>setError(workspaceError(e)));}} onClose={()=>setExplorerOpen(false)} storageKey={`pms-note-tree:${user?.id}`}/>
